import { Document, Page, Heading, Text, Table, Button, render } from '@pyreon/document'

declare function sendMail(m: { to: string; subject: string; html: string; attachments: { filename: string; content: Uint8Array }[] }): Promise<void>
type Line = { item: string; qty: number; price: string }
const Invoice = (props: { no: string; customer: string; lines: Line[]; payUrl: string }) => (
  <Document title={`Invoice ${props.no}`}>
    <Page>
      <Heading>Invoice {props.no}</Heading>
      <Text>Billed to {props.customer}</Text>
      <Table columns={['Item', 'Qty', 'Price']} rows={props.lines.map((l) => [l.item, l.qty, l.price])} striped />
      <Button href={props.payUrl}>Pay now</Button>
    </Page>
  </Document>
)
async function sendInvoice(no: string, customer: string, email: string, lines: Line[]) {
  const doc = <Invoice no={no} customer={customer} lines={lines} payUrl={`https://pay.example.com/${no}`} />
  await sendMail({
    to: email,
    subject: `Invoice ${no}`,
    html: await render(doc, 'email'),
    attachments: [{ filename: `invoice-${no}.pdf`, content: await render(doc, 'pdf') }],
  })
}

