import { Document, Heading, Text, Link, render } from '@pyreon/document'

async function postWeekly(webhookUrl: string, signups: number, churned: number) {
  const summary = (
    <Document>
      <Heading>Weekly numbers</Heading>
      <Text>{signups} sign-ups, {churned} cancellations.</Text>
      <Link href="https://dash.example.com/weekly">Open the dashboard</Link>
    </Document>
  )
  await fetch(webhookUrl, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: await render(summary, 'slack'),
  })
}
